// Enumerate the draft queue from one git-tree call.
//
// Ordering is a literal port of publish.py `_draft_posts()`:
//   sorted(dirs) then sorted(dir.glob('post_*.md')) inside each dir
// i.e. plain lexicographic on the directory name, then on the file name
// (so post_10.md sorts before post_2.md, exactly as Python does). Do not
// "improve" this into a natural sort — it changes which post goes out.
const tree = $input.first().json.tree || [];
if ($input.first().json.truncated) {
  throw new Error('git tree response was truncated — the repo outgrew a single tree call');
}

const paths = new Set(tree.filter((e) => e.type === 'blob').map((e) => e.path));
const drafts = [...paths]
  .filter((p) => /^linkedin\/drafts\/[^/]+\/post_\d+\.md$/.test(p))
  .sort((a, b) => {
    const A = a.split('/');
    const B = b.split('/');
    return A[2] < B[2] ? -1 : A[2] > B[2] ? 1 : A[3] < B[3] ? -1 : A[3] > B[3] ? 1 : 0;
  });

if (!drafts.length) throw new Error('no drafts found under linkedin/drafts/');

// publish.py attaches `post_N.png` when it sits next to the markdown.
return drafts.map((p) => ({ json: { path: p, pngPath: paths.has(p.replace(/\.md$/, '.png')) ? p.replace(/\.md$/, '.png') : null } }));

// Port of publish.py `cmd_next()` — pick the post to publish, or nothing.
//
// Two independent stops, both from publish.py:
//   1. ANY draft already carries today's `published:` date  -> "Already published
//      today". This is the idempotency guard; it is what makes a manual re-run or
//      an overlapping trigger safe. Returning [] here stops the workflow.
//   2. no draft without a `published:` marker               -> queue empty
const cfg = $('Config').first().json;
const meta = new Map($('Enumerate drafts').all().map((i) => [i.json.path, i.json]));

// publish.py `_split_frontmatter`: ^---\n(.*?)\n---\n\n?(.*)$ with DOTALL.
const splitFrontmatter = (text) => {
  const m = /^---\n([\s\S]*?)\n---\n\n?([\s\S]*)$/.exec(text);
  if (!m) throw new Error('no frontmatter');
  return { fm: m[1], body: m[2] };
};

const drafts = $input.all().map((item) => {
  const j = item.json;
  const text = Buffer.from(j.content, 'base64').toString('utf8');
  const { fm, body } = splitFrontmatter(text);
  return { path: j.path, sha: j.sha, fm, body };
});

// The pod runs on Europe/Paris (TZ in the n8n ConfigMap), matching the CronJob
// timezone the drip schedule was specified in.
const today = new Date().toLocaleDateString('en-CA', { timeZone: cfg.timezone });

// publish.py `_published_today`: ^published:\s*(YYYY-MM-DD) anywhere in frontmatter.
// Tolerates a trailing comment on the line, e.g. "published: ... # posted manually".
for (const d of drafts) {
  const m = /^published:\s*(\d{4}-\d{2}-\d{2})/m.exec(d.fm);
  if (m && m[1] === today) return [];
}

// publish.py `_is_published` is a SUBSTRING test on the frontmatter, not a regex.
const next = drafts.find((d) => !d.fm.includes('published:'));
if (!next) return [];

// publish.py: alt text is the `angle:` frontmatter value, else "cover".
const angle = /^angle:\s*(.+)$/m.exec(next.fm);

return [
  {
    json: {
      path: next.path,
      sha: next.sha,
      fm: next.fm,
      body: next.body,
      pngPath: meta.get(next.path)?.pngPath ?? null,
      altText: angle ? angle[1].trim() : 'cover',
      remaining: drafts.filter((d) => !d.fm.includes('published:')).length,
    },
  },
];

// Port of publish.py `publish_file()` payload construction.
const cfg = $('Config').first().json;
const draft = $('Select draft').first().json;

// publish.py `_ESCAPE_CHARS`. Note what is NOT here: '#' is deliberately left
// unescaped so hashtags keep working, and '*', '_', '~' are not escaped either.
// Widening this set turns every hashtag into literal text.
const ESCAPE_CHARS = '\\|{}@[]()<>';
const escapeCommentary = (s) =>
  Array.from(s)
    .map((c) => (ESCAPE_CHARS.includes(c) ? '\\' + c : c))
    .join('');

const post = {
  author: cfg.personUrn,
  commentary: escapeCommentary(draft.body.trim()),
  visibility: 'PUBLIC',
  distribution: {
    feedDistribution: 'MAIN_FEED',
    targetEntities: [],
    thirdPartyDistributionChannels: [],
  },
  lifecycleState: 'PUBLISHED',
  isReshareDisabledByAuthor: false,
};

// The image nodes run with onError: continueRegularOutput, mirroring publish.py's
// "log the body and post text-only rather than abort". imageUrn is null when the
// draft has no PNG, or when the upload failed.
let imageUrn = null;
try {
  imageUrn = $('Init image upload').first().json?.value?.image ?? null;
} catch (e) {
  imageUrn = null;
}
const uploaded = imageUrn && $('Upload image bytes').first().json?.__uploaded !== false;

if (uploaded) {
  post.content = { media: { id: imageUrn, altText: draft.altText } };
}

return [
  {
    json: {
      post,
      imageAttached: Boolean(uploaded),
      imageSkipped: draft.pngPath && !uploaded ? draft.pngPath : null,
    },
  },
];

// Port of publish.py's frontmatter rewrite (its lines 252-254), then base64 for
// the GitHub Contents API. Writing through the API instead of clone/commit/push
// means the file `sha` read a few seconds ago is the optimistic-concurrency
// token: if anything else touched this draft meanwhile GitHub returns 409 and
// the execution fails loudly rather than clobbering.
const draft = $('Select draft').first().json;
const built = $('Build payload').first().json;
const resp = $input.first().json;

const postUrn = (resp.headers || {})['x-restli-id'] || '';
if (!postUrn) throw new Error('LinkedIn returned no x-restli-id header — cannot record the marker');

// publish.py uses datetime.now().isoformat() (naive, pod-local). Same shape here,
// in the workflow timezone. Only the date part is ever parsed back.
const cfg = $('Config').first().json;
const parts = new Intl.DateTimeFormat('sv-SE', {
  timeZone: cfg.timezone,
  year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', second: '2-digit',
  hour12: false,
}).format(new Date());
const nowIso = parts.replace(' ', 'T');

const newFm = `${draft.fm}\npublished: ${nowIso}\npost_urn: ${postUrn}`;
const newText = `---\n${newFm}\n---\n\n${draft.body}`;

return [
  {
    json: {
      path: draft.path,
      sha: draft.sha,
      postUrn,
      imageAttached: built.imageAttached,
      imageSkipped: built.imageSkipped,
      contentBase64: Buffer.from(newText, 'utf8').toString('base64'),
    },
  },
];
